            import collections
            d = collections.defaultdict(int)
            for row in nums:
                for i in row:
                    d[i] += 1
            temp = []
            import heapq
            for key, v in d.items():
                if len(temp) < k:
                    temp.append((v, key))
                    if len(temp) == k:
                        heapq.heapify(temp)
                else:
